package vn.biz04.service;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.beans.factory.annotation.Value;
import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import vn.biz04.data.Store;
import vn.biz04.domain.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
@Service
@Transactional
public class ContractService {
    private final Store db;private final Access access;private final EntityManager em;private final BigDecimal fee;private final ProposalService proposals;private final MilestonePlanService plans;private final ContractSnapshots snapshots;private final Clock clock;
    public ContractService(Store db,Access access,EntityManager em,@Value("${biz.fee-rate:0.10}")BigDecimal fee,ProposalService proposals,MilestonePlanService plans,ContractSnapshots snapshots,Clock clock){this.db=db;this.access=access;this.em=em;this.fee=fee;this.proposals=proposals;this.plans=plans;this.snapshots=snapshots;this.clock=clock;}
    public HopDong select(Long actor,Long proposalId){
        ProposalService.Locked locked=proposals.lockOwner(actor,proposalId);DeXuat d=locked.proposal();YeuCau y=locked.request();
        HopDong existing=db.first("from HopDong h where h.maYeuCau=:y",HopDong.class,"y",y.getMaYeuCau()).orElse(null);
        if(existing!=null){Checks.require(Objects.equals(existing.getMaDeXuat(),proposalId),"Yêu cầu đã có hợp đồng với đề xuất khác.");return existing;}
        throw new BusinessException("Giao dịch mới cần thống nhất kế hoạch mốc và rà soát lập hợp đồng điện tử. Không tạo qua đường dẫn cũ.");
    }

    private void draft(HopDong h,Long actor){access.member(h,actor);Checks.require(h.getMaKeHoach()==null,"Mốc, giá và phạm vi đã chốt chỉ được lấy từ bản kế hoạch. Hãy dùng luồng rà soát điều khoản điện tử.");Checks.require("CHO_XAC_NHAN".equals(h.getTrangThai())&&Objects.equals(access.customer(h),actor),"Chỉ khách hàng được sửa hợp đồng chờ xác nhận.");}
    private void changed(HopDong h){h.setPhienBan(h.getPhienBan()+1);h.setPhienBanKhachXacNhan(null);h.setPhienBanChuyenGiaXacNhan(null);}
    public void terms(Long actor,Long id,String text,BigDecimal total){HopDong h=db.lock(id);draft(h,actor);h.setNoiDungThoaThuan(Checks.text(text,10,10000,"Thỏa thuận"));h.setTongGiaTri(Checks.money(total,false));changed(h);access.audit(actor,"HopDong",id,"SUA_PHIEN_BAN",String.valueOf(h.getPhienBan()));}
    public MocNghiemThu milestone(Long actor,Long id,Long mid,int order,String name,String content,String criteria,BigDecimal amount,LocalDate due){
        HopDong h=db.lock(id);draft(h,actor);Checks.require(order>0&&order<=100,"Thứ tự mốc từ 1 đến 100.");Checks.require(due!=null,"Cần hạn bàn giao.");
        MocNghiemThu m=mid==null?new MocNghiemThu():db.get(MocNghiemThu.class,mid);Checks.require(mid==null||Objects.equals(m.getMaHopDong(),id),"Mốc không thuộc hợp đồng.");
        for(MocNghiemThu old:milestones(id))Checks.require(Objects.equals(old.getMaMocNghiemThu(),mid)||old.getThuTu()!=order,"Thứ tự mốc đã có.");
        m.setMaHopDong(id);m.setThuTu(order);m.setTenMoc(Checks.text(name,3,255,"Tên mốc"));m.setNoiDung(Checks.text(content,5,10000,"Nội dung mốc"));m.setTieuChiNghiemThu(Checks.text(criteria,5,10000,"Tiêu chí"));m.setSoTien(Checks.money(amount,false));m.setHanBanGiao(due.atTime(23,59).atZone(ZoneId.of("Asia/Ho_Chi_Minh")).withZoneSameInstant(ZoneOffset.UTC).toLocalDateTime());m.setTrangThai("CHO_KY_QUY");if(mid==null)db.save(m);changed(h);access.audit(actor,"MocNghiemThu",m.getMaMocNghiemThu(),"LUU_MOC",null);return m;
    }
    public void removeMilestone(Long actor,Long id,Long mid){HopDong h=db.lock(id);draft(h,actor);MocNghiemThu m=db.get(MocNghiemThu.class,mid);Checks.require(Objects.equals(m.getMaHopDong(),id),"Mốc không thuộc hợp đồng.");access.audit(actor,"MocNghiemThu",mid,"XOA_MOC_NHAP",null);db.remove(m);changed(h);}
    public List<MocNghiemThu> milestones(Long id){return db.list("from MocNghiemThu m where m.maHopDong=:h order by m.thuTu",MocNghiemThu.class,"h",id);}
    public void confirm(Long actor,Long id,int version){
        HopDong h=db.lock(id);access.member(h,actor);Checks.require(h.getMaKeHoach()==null,"Hợp đồng điện tử cần rà soát và xác nhận bằng ticket đúng phiên bản.");Checks.require(Set.of("CHO_XAC_NHAN","CHO_TIEP_TUC").contains(h.getTrangThai()),"Hợp đồng không chờ xác nhận.");Checks.require(h.getPhienBan()==version,"Nội dung đã thay đổi. Hãy tải lại và đọc phiên bản mới.");
        List<MocNghiemThu> ms=milestones(id);Checks.require(!ms.isEmpty()&&ms.stream().map(MocNghiemThu::getSoTien).reduce(BigDecimal.ZERO,BigDecimal::add).compareTo(h.getTongGiaTri())==0,"Cần ít nhất một mốc; tổng tiền mốc phải bằng tổng hợp đồng.");
        if(Objects.equals(actor,access.customer(h)))h.setPhienBanKhachXacNhan(version);else h.setPhienBanChuyenGiaXacNhan(version);
        if(Objects.equals(h.getPhienBanKhachXacNhan(),version)&&Objects.equals(h.getPhienBanChuyenGiaXacNhan(),version)){h.setTrangThai("DANG_THUC_HIEN");completeIfSettled(h);}
        access.audit(actor,"HopDong",id,"XAC_NHAN_PHIEN_BAN",String.valueOf(version));
    }
    public void cancel(Long actor,Long id){HopDong h=db.lock(id);access.member(h,actor);Checks.require(h.getMaKeHoach()==null,"Hãy rà soát hủy hợp đồng điện tử đúng phiên bản.");Checks.require("CHO_XAC_NHAN".equals(h.getTrangThai()),"Chỉ hủy trực tiếp trước khi có hiệu lực.");h.setTrangThai("DA_HUY");h.setNgayKetThuc(access.now());if(h.getMaYeuCau()!=null)db.get(YeuCau.class,h.getMaYeuCau()).setTrangThai("DA_DONG");if(h.getMaDeXuat()!=null)db.get(DeXuat.class,h.getMaDeXuat()).setTrangThai("BI_TU_CHOI");for(MocNghiemThu m:milestones(id))m.setTrangThai("DA_HUY");access.audit(actor,"HopDong",id,"HUY_TRUOC_HIEU_LUC",null);}
    public void completeIfSettled(HopDong h){List<MocNghiemThu> ms=milestones(h.getMaHopDong());if("DANG_THUC_HIEN".equals(h.getTrangThai())&&!ms.isEmpty()&&ms.stream().allMatch(m->"DA_TAT_TOAN".equals(m.getTrangThai()))){h.setTrangThai("HOAN_THANH");h.setNgayKetThuc(access.now());if(h.getMaYeuCau()!=null)db.get(YeuCau.class,h.getMaYeuCau()).setTrangThai("DA_DONG");access.audit(null,"HopDong",h.getMaHopDong(),"HOAN_THANH",null);}}
    public void terminate(HopDong h){for(MocNghiemThu m:milestones(h.getMaHopDong()))if(!"DA_TAT_TOAN".equals(m.getTrangThai()))m.setTrangThai("DA_HUY");h.setTrangThai("DA_CHAM_DUT");h.setNgayKetThuc(access.now());if(h.getMaYeuCau()!=null)db.get(YeuCau.class,h.getMaYeuCau()).setTrangThai("DA_DONG");}
    private OffsetDateTime utc(){return OffsetDateTime.now(clock).withOffsetSameInstant(ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS);}
    public record Preview(MilestonePlanService.View plan,ContractSnapshots.Body body){}
    @Transactional(readOnly=true) public Preview previewElectronic(Long actor,String kind,Long source,ElectronicContractForm form){var plan=plans.forContract(actor,kind,source,false);if(plan.contractId()!=null)return new Preview(plan,null);var terms=plan.latest().terms();var validated=MilestonePlanRules.validate(MilestonePlanRules.form(terms),plan.source().total(),plan.source().days(),terms.reason()!=null);Checks.require(validated.equals(terms),"Kế hoạch cần được rà soát lại trước khi lập hợp đồng.");return new Preview(plan,snapshots.draft(plan,form));}
    public HopDong createElectronic(Long actor,String kind,Long source,int expectedPlan,ContractSnapshots.Body reviewed){
        var plan=plans.forContract(actor,kind,source,true);if(plan.contractId()!=null)return db.get(HopDong.class,plan.contractId());
        Checks.require(plan.current()==expectedPlan&&reviewed.planId().equals(plan.planId())&&reviewed.planVersion()==expectedPlan,"Phiên bản kế hoạch đã thay đổi. Hãy rà soát lại.");
        var fresh=snapshots.draft(plan,snapshots.form(reviewed));Checks.require(snapshots.fingerprint(fresh).equals(snapshots.fingerprint(reviewed)),"Thông tin nguồn, hồ sơ hoặc đơn vị vận hành đã thay đổi. Hãy rà soát lại trước khi lập hợp đồng.");
        var h=new HopDong();if(kind.equals("de-xuat")){var proposal=db.get(DeXuat.class,source);h.setMaYeuCau(proposal.getMaYeuCau());h.setMaDeXuat(source);}
        h.setMaKeHoach(plan.planId());h.setPhienBanKeHoach(expectedPlan);h.setMaKhachHang(plan.source().customer());h.setMaChuyenGia(plan.source().expert());h.setNoiDungThoaThuan(plan.source().scope());h.setTongGiaTri(plan.source().total());h.setTyLePhi(reviewed.milestones().rate());h.setQuyTacPhi(reviewed.milestones().feeRule());h.setQuyTacBatDau(ContractSnapshots.START_RULE);h.setPhienBan(1);h.setTrangThai("CHO_XAC_NHAN");h.setNgayLap(utc());h.setDauKiemNoiDung("0".repeat(64));db.save(h);snapshots.save(h,actor,reviewed,utc());
        for(var item:reviewed.milestones().items()){var m=new MocNghiemThu();m.setMaHopDong(h.getMaHopDong());m.setThuTu(item.position());m.setTenMoc(item.title());m.setNoiDung(item.work());m.setSanPhamThoaThuan(item.deliverable());m.setTieuChiNghiemThu(item.criteria());m.setSoTien(item.amount());m.setDinhDanhMoc(item.stableKey());m.setDonViHan(item.unit());m.setHanTuongDoi(item.due());m.setLaMocCuoi(item.position()==reviewed.milestones().items().size());m.setSoLanChinhSuaToiDa(item.revisions());m.setTrangThai("CHO_KY_QUY");db.save(m);}
        if(h.getMaYeuCau()!=null){db.get(YeuCau.class,h.getMaYeuCau()).setTrangThai("DANG_THUONG_LUONG");for(var p:db.list("from DeXuat p where p.maYeuCau=:y",DeXuat.class,"y",h.getMaYeuCau()))if(!p.getMaDeXuat().equals(h.getMaDeXuat())&&"DANG_GUI".equals(p.getTrangThai()))p.setTrangThai("BI_TU_CHOI");}
        access.audit(actor,"HopDong",h.getMaHopDong(),"LAP_HOP_DONG_DIEN_TU","Kế hoạch "+plan.planId()+"; phiên bản "+expectedPlan);return h;
    }
    private void electronicParty(HopDong h,Long actor){Checks.require(h.getMaKeHoach()!=null,"Đây là hợp đồng thuộc luồng cũ.");if(access.user(actor).getLaQuanTriVien()||!access.party(h,actor))throw new org.springframework.security.access.AccessDeniedException("Chỉ hai bên được xác nhận cho chính mình; admin chỉ được đọc.");}
    @Transactional(readOnly=true) public ContractSnapshots.Read electronic(Long actor,Long id,int version){var h=db.get(HopDong.class,id);access.read(h,actor);Checks.require(h.getMaKeHoach()!=null,"Hợp đồng cũ dùng màn hình hiện có.");return snapshots.read(h,version<1?h.getPhienBan():version);}
    @Transactional(readOnly=true) public ContractSnapshots.Read reviewElectronicAction(Long actor,Long id,int expected,String action){var h=db.get(HopDong.class,id);electronicParty(h,actor);current(h,expected,h.getDauKiemNoiDung());Checks.require(action.equals("CONFIRM")?Set.of("CHO_XAC_NHAN","CHO_TIEP_TUC").contains(h.getTrangThai()):"CHO_XAC_NHAN".equals(h.getTrangThai()),"Hợp đồng không còn chờ thao tác này.");if(action.equals("AMEND"))Checks.require(actor.equals(h.getMaKhachHang()),"Chỉ khách hàng được đề xuất thay đổi điều khoản trước hiệu lực.");return snapshots.read(h,expected);}
    private void current(HopDong h,int expected,String digest){Checks.require(h.getPhienBan()==expected&&Objects.equals(h.getDauKiemNoiDung(),digest),"Phiên bản hợp đồng đã thay đổi. Hãy mở lại và rà soát bản mới nhất.");var read=snapshots.read(h,expected);Checks.require(read.digest().equals(digest)&&read.document().body().planId().equals(h.getMaKeHoach())&&read.document().body().planVersion()==h.getPhienBanKeHoach()&&read.document().body().milestones().rate().compareTo(h.getTyLePhi())==0&&read.document().body().milestones().feeRule().equals(h.getQuyTacPhi())&&ContractSnapshots.START_RULE.equals(h.getQuyTacBatDau())&&read.document().body().customer().id().equals(h.getMaKhachHang())&&read.document().body().expert().id().equals(h.getMaChuyenGia())&&read.document().body().milestones().total().compareTo(h.getTongGiaTri())==0,"Hợp đồng không khớp bản chụp đã rà soát.");}
    public void confirmElectronic(Long actor,Long id,int expected,String digest,String strokes){var h=db.lock(id);electronicParty(h,actor);current(h,expected,digest);var proof=db.first("from XacNhanHopDong x where x.contract=:h and x.version=:v and x.actor=:a",XacNhanHopDong.class,"h",id,"v",expected,"a",actor);if(proof.isPresent()){Checks.require(proof.get().digest.equals(digest),"Dấu kiểm tra xác nhận không khớp.");return;}Checks.require(Set.of("CHO_XAC_NHAN","CHO_TIEP_TUC").contains(h.getTrangThai()),"Hợp đồng không chờ xác nhận.");
        var x=new XacNhanHopDong();x.contract=id;x.version=expected;x.actor=actor;x.digest=digest;x.at=utc();x.signature=ContractSignature.png(strokes);db.save(x);if(actor.equals(h.getMaKhachHang()))h.setPhienBanKhachXacNhan(expected);else h.setPhienBanChuyenGiaXacNhan(expected);
        if(Objects.equals(h.getPhienBanKhachXacNhan(),expected)&&Objects.equals(h.getPhienBanChuyenGiaXacNhan(),expected)){h.setTrangThai("DANG_THUC_HIEN");completeIfSettled(h);}access.audit(actor,"HopDong",id,"XAC_NHAN_HOP_DONG_DIEN_TU","Phiên bản "+expected+"; "+digest);
    }
    public void amendElectronic(Long actor,Long id,int expected,String digest,ContractSnapshots.Body reviewed){var h=db.lock(id);electronicParty(h,actor);Checks.require(actor.equals(h.getMaKhachHang())&&"CHO_XAC_NHAN".equals(h.getTrangThai()),"Chỉ khách hàng được điều chỉnh điều khoản trước hiệu lực.");current(h,expected,digest);var old=snapshots.read(h,expected).document().body();var amended=snapshots.amended(old,snapshots.form(reviewed));Checks.require(amended.equals(reviewed),"Không được sửa nguồn, mốc, phí hoặc thông tin các bên trong form điều khoản.");Checks.require(!old.equals(reviewed),"Điều khoản chưa thay đổi.");changed(h);snapshots.save(h,actor,reviewed,utc());access.audit(actor,"HopDong",id,"DIEU_CHINH_DIEU_KHOAN","Phiên bản "+h.getPhienBan());}
    public void cancelElectronic(Long actor,Long id,int expected,String digest,String reason){var h=db.lock(id);electronicParty(h,actor);current(h,expected,digest);Checks.require("CHO_XAC_NHAN".equals(h.getTrangThai()),"Chỉ hủy trước hiệu lực.");String explanation=Checks.text(reason,5,2000,"Lý do hủy");h.setTrangThai("DA_HUY");h.setNgayKetThuc(access.now());for(var m:milestones(id))m.setTrangThai("DA_HUY");if(h.getMaYeuCau()!=null)db.get(YeuCau.class,h.getMaYeuCau()).setTrangThai("DA_DONG");if(h.getMaDeXuat()!=null)db.get(DeXuat.class,h.getMaDeXuat()).setTrangThai("BI_TU_CHOI");access.audit(actor,"HopDong",id,"HUY_HOP_DONG_DIEN_TU",explanation);}
    public void requireFundingConsent(HopDong h){if(h.getMaKeHoach()==null)return;current(h,h.getPhienBan(),h.getDauKiemNoiDung());Checks.require(Objects.equals(h.getPhienBanKhachXacNhan(),h.getPhienBan())&&Objects.equals(h.getPhienBanChuyenGiaXacNhan(),h.getPhienBan()),"Hai bên cần xác nhận cùng phiên bản trước ký quỹ.");Checks.require(db.count("select count(x) from XacNhanHopDong x where x.contract=:h and x.version=:v and x.digest=:d and x.actor in (:a,:b)","h",h.getMaHopDong(),"v",h.getPhienBan(),"d",h.getDauKiemNoiDung(),"a",h.getMaKhachHang(),"b",h.getMaChuyenGia())==2,"Thiếu bằng chứng xác nhận hợp đồng điện tử.");}
    public void recordFirstFunding(HopDong h,MocNghiemThu first,GiaoDich payment){if(h.getMaKeHoach()==null||h.getThoiDiemBatDau()!=null||first.getThuTu()!=1||!"THANH_CONG".equals(payment.getTrangThai()))return;requireFundingConsent(h);Checks.require(ContractSnapshots.START_RULE.equals(h.getQuyTacBatDau())&&payment.getNgayHoanTat()!=null,"Thiếu sự kiện bắt đầu hợp lệ.");var start=payment.getNgayHoanTat().atOffset(ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MICROS);var document=snapshots.read(h,h.getPhienBan()).document();var body=document.body();var date=start.atZoneSameInstant(ZoneId.of("Asia/Ho_Chi_Minh")).toLocalDate();LocalDate previous=null;
        var rows=milestones(h.getMaHopDong());Checks.require(rows.size()==body.milestones().items().size(),"Mốc vận hành không khớp kế hoạch đã chốt.");for(int i=0;i<rows.size();i++){var row=rows.get(i);var item=body.milestones().items().get(i);Checks.require(Objects.equals(row.getDinhDanhMoc(),item.stableKey())&&row.getSoTien().compareTo(item.amount())==0,"Nội dung mốc không khớp bản chụp.");var due=MilestonePlanRules.resolve(date,item,body.source().days(),i==rows.size()-1,body.milestones().deadlineRule());Checks.require(previous==null||!due.isBefore(previous),"Lịch bàn giao không được giảm.");previous=due;row.setHanBanGiao(due.atTime(23,59).atZone(ZoneId.of("Asia/Ho_Chi_Minh")).withZoneSameInstant(ZoneOffset.UTC).toLocalDateTime());}Checks.require(previous!=null&&previous.equals(date.plusDays(body.source().days())),"Mốc cuối không khớp thời lượng đã thống nhất.");h.setThoiDiemBatDau(start);access.audit(h.getMaKhachHang(),"HopDong",h.getMaHopDong(),"BAT_DAU_TU_KY_QUY_DAU",null);
    }
    public void resumeVersion(HopDong h,Long actor){var body=h.getMaKeHoach()==null?null:snapshots.read(h,h.getPhienBan()).document().body();changed(h);if(body!=null)snapshots.save(h,actor,body,utc());}
}
